// both armed limits, PlanGuarded, and rollback evidence.
func TestCheckoutSyncPlan_RunCheckoutSync_GuardedApprovedRunPersistsGuardedVersionWithLimits(t *testing.T) {
	dir, ws := cspFixture(t)
