	}
	if tx.MaxReplayTotal == nil || *tx.MaxReplayTotal != 5 {
		t.Fatalf("MaxReplayTotal = %v, want a pointer to 5: the armed limit must be persisted", tx.MaxReplayTotal)
	}
	if tx.Route != RouteLegacy {
