func TestCheckoutSyncPlan_ContinueCheckoutSync_ArmedResumeUpgradesV2Transaction(t *testing.T) {
	dir, ws := cspFixture(t)
	feature := "feat-resume-upgrade"
	fp := ws.FeaturePath(feature)
