func TestCheckoutSyncModes_ContinueMismatchAndVersionRules(t *testing.T) {
	dir, fp := checkoutModeFixture(t)
	clearStepHook(t)
	internal.StepHook = func(stage internal.CheckoutStage, i int) error {
		if stage == internal.StageRebased {
			return errStop
		}
