	}
	policy := internal.SyncRunPolicy{Fetch: internal.SyncFetchDisabled, Propagation: internal.SyncPropagationFull, ScopeKind: internal.SyncScopeSubtree, Selector: "feat-a"}
	_, _ = captureRun(t, func() error {
