func syncStateRefExternal(fx *goldenFixture) syncStateRef {
	return syncStateRef{
		surface: "state-sync-state.yaml",
		path:    internal.SyncStatePath(fx.featurePath),
		spec:    stateCompareSpec{DynamicKeys: syncStateDynamicKeys},
