import (
	"encoding/base64"
	"fmt"
	"path/filepath"
	"reflect"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

func syncTransactionAbsolutePath(path string) bool {
	return filepath.IsAbs(path) && filepath.Clean(path) == path && !strings.ContainsAny(path, "\x00\r\n")
}

func validateSyncTransactionRelationships(tx *SyncTransaction, before []byte) error {
	invalid := func(detail string) error { return fmt.Errorf("invalid sync transaction evidence: %s", detail) }
	if _, err := time.Parse(time.RFC3339, tx.CreatedAt); err != nil {
		return invalid("created_at")
	}
	if tx.UpdatedAt != "" {
		if _, err := time.Parse(time.RFC3339, tx.UpdatedAt); err != nil {
			return invalid("updated_at")
		}
	}
	if !syncTransactionAbsolutePath(tx.Metadata.Path) || filepath.Base(tx.Metadata.Path) != "stack.yaml" {
		return invalid("metadata path")
	}
	if tx.Metadata.IntentBase64 != "" || tx.Metadata.IntentSHA256 != "" || tx.Metadata.IntentPending {
		intent, err := base64.StdEncoding.DecodeString(tx.Metadata.IntentBase64)
		if err != nil || syncTransactionHash(intent) != tx.Metadata.IntentSHA256 {
			return invalid("metadata intent")
		}
	}
	if tx.Ready && tx.Phase == SyncTxnPreparing || !tx.Ready && len(tx.Actions) != 0 {
		return invalid("readiness disagrees with progress")
	}
	rollingBack := tx.Rollback.StartedAt != ""
	if tx.Completion != "" {
		if tx.Completion != "forward-complete" && tx.Completion != "cancelled-before-mutation" {
			return invalid("unknown completion decision")
		}
		if tx.Phase != SyncTxnCleanup || rollingBack {
			return invalid("completion must be forward cleanup only")
		}
		if tx.Completion == "cancelled-before-mutation" && (len(tx.Actions) != 0 || tx.Publication.IntentDurable ||
			tx.Metadata.ExpectedSHA256 != tx.Metadata.BeforeSHA256) {
			return invalid("cancelled transaction contains effects")
		}
	} else if tx.Phase == SyncTxnCleanup && !rollingBack {
		return invalid("cleanup lacks a durable completion decision")
	}
	if rollingBack {
		if _, err := time.Parse(time.RFC3339, tx.Rollback.StartedAt); err != nil {
			return invalid("rollback timestamp")
		}
		if tx.Phase != SyncTxnRollingBack && tx.Phase != SyncTxnCleanup {
			return invalid("rollback must remain forward-disabled")
		}
	} else if tx.Phase == SyncTxnRollingBack || tx.Rollback.Stage != "" ||
		tx.Rollback.MetadataRestored || len(tx.Rollback.HoldersRestored) != 0 || len(tx.Rollback.CompletedRepos) != 0 {
		return invalid("rollback progress without rollback intent")
	}
	if tx.Publication.IntentDurable {
		if _, err := time.Parse(time.RFC3339, tx.Publication.StartedAt); err != nil || rollingBack {
			return invalid("publication and rollback are mutually exclusive")
		}
	} else if tx.Phase == SyncTxnPublished || tx.Publication.StartedAt != "" ||
		tx.Publication.CurrentEntry != "" || tx.Publication.Current != nil ||
		len(tx.Publication.Intents) != 0 || len(tx.Publication.Results) != 0 {
		return invalid("publication result without publication intent")
	}
	if (tx.Publication.Current == nil) != (tx.Publication.CurrentEntry == "") {
		return invalid("publication current intent")
	}
	if tx.Metadata.Restored != tx.Rollback.MetadataRestored ||
		tx.Metadata.Restored && tx.Metadata.ExpectedSHA256 != tx.Metadata.BeforeSHA256 {
		return invalid("metadata restoration progress")
	}
	var stack Stack
	if err := yaml.Unmarshal(before, &stack); err != nil {
		return invalid("metadata preimage is not a stack")
	}
	entries := make(map[string]string, len(stack.Branches))
	for _, entry := range stack.Branches {
		if entry.Name == "" || entries[entry.Name] != "" {
			return invalid("ambiguous stack entry identity")
		}
		entries[entry.Name] = "refs/heads/" + entry.GitBranch()
	}
	selected := make(map[string]bool, len(tx.Selected))
	for _, name := range tx.Selected {
		if name == "" || selected[name] || entries[name] == "" {
			return invalid("selected names")
		}
		selected[name] = true
	}
	repos := make(map[string]*SyncTransactionRepo, len(tx.Repositories))
	holders := map[string]bool{}
	attributed := map[string]bool{}
	for i := range tx.Repositories {
		repo := &tx.Repositories[i]
		repos[repo.CommonDir] = repo
		for _, ref := range repo.Refs {
			if ref.Moved != (ref.ExpectedSHA != ref.PreimageSHA) ||
				ref.Restored && (!rollingBack || ref.ExpectedSHA != ref.PreimageSHA) ||
				repo.RefsRestored && !ref.Restored {
				return invalid("ref movement/restoration progress")
			}
			if repo.PinsRemoved && (ref.Pinned || ref.PinDeletePending) ||
				ref.PinDeletePending && tx.Phase != SyncTxnCleanup {
				return invalid("pin deletion progress")
			}
			if tx.Ready && tx.Phase != SyncTxnCleanup && !ref.Pinned {
				return invalid("ready transaction lost a preimage pin")
			}
			for _, name := range ref.SelectedNames {
				if !selected[name] || attributed[name] || entries[name] != ref.Ref {
					return invalid("selected branch attribution")
				}
				attributed[name] = true
			}
		}
		for _, holder := range repo.Holders {
			if !syncTransactionAbsolutePath(holder.Path) || holders[holder.Path] ||
				!reparentStateOID(holder.OriginalHEAD, repo.OIDWidth) ||
				!reparentStateOID(holder.ExpectedHEAD, repo.OIDWidth) {
				return invalid("holder identity")
			}
			holders[holder.Path] = true
			if !holder.OriginalDetached && (holder.OriginalHeadPinned || holder.HeadPinDeletePending) ||
				holder.HeadPinDeletePending && tx.Phase != SyncTxnCleanup ||
				repo.PinsRemoved && (holder.OriginalHeadPinned || holder.HeadPinDeletePending) {
				return invalid("original detached HEAD pin progress")
			}
			if tx.Ready && tx.Phase != SyncTxnCleanup && holder.OriginalDetached && !holder.OriginalHeadPinned {
				return invalid("ready transaction lost a detached HEAD pin")
			}
			if target := holder.ForwardRestoreTarget; target != nil {
				if target.Path != holder.Path || target.Branch != holder.OriginalBranch ||
					target.Detached != holder.OriginalDetached ||
					!reparentStateOID(target.HEAD, repo.OIDWidth) {
					return invalid("forward checkout restoration intent")
				}
			}
			for _, position := range []struct {
				branch   string
				detached bool
			}{{holder.OriginalBranch, holder.OriginalDetached}, {holder.ExpectedBranch, holder.ExpectedDetached}} {
				if position.detached != (position.branch == "") ||
					!position.detached && !reparentStateRef("refs/heads/"+position.branch) {
					return invalid("holder attachment")
				}
			}
			if (holder.DetachPending || holder.RestorePending || holder.Restored || holder.Detached) && !rollingBack {
				return invalid("holder rollback progress before rollback intent")
			}
		}
	}
	if len(attributed) != len(selected) {
		return invalid("selected branch lacks a preimage")
	}
	if mode := WorkspaceMode(tx.WorkspaceMode); mode == ModeCheckout && len(repos) > 1 {
		return invalid("checkout transaction spans repositories")
	}
	validateRepoList := func(list []string, predicate func(*SyncTransactionRepo) bool) bool {
		seen := map[string]bool{}
		for _, common := range list {
			if repos[common] == nil || seen[common] || !predicate(repos[common]) {
				return false
			}
			seen[common] = true
		}
		return true
	}
	if !validateRepoList(tx.Rollback.CompletedRepos, func(repo *SyncTransactionRepo) bool { return repo.RefsRestored }) ||
		!validateRepoList(tx.Rollback.PinsRemovedRepos, func(repo *SyncTransactionRepo) bool { return repo.PinsRemoved }) {
		return invalid("repository cleanup progress")
	}
	for _, path := range tx.Rollback.HoldersRestored {
		if !holders[path] {
			return invalid("unknown restored holder")
		}
	}
	refHistory := make(map[string]map[string]string, len(tx.Repositories))
	for _, repo := range tx.Repositories {
		refHistory[repo.CommonDir] = map[string]string{}
		for _, ref := range repo.Refs {
			refHistory[repo.CommonDir][ref.Ref] = ref.PreimageSHA
		}
	}
	for i, action := range tx.Actions {
		repo := repos[action.RepoCommonDir]
		if action.Sequence != i+1 || action.Kind != "rebase" || repo == nil ||
			!selected[action.Entry] || !syncTransactionAbsolutePath(action.ContextPath) ||
			!holders[action.ContextPath] {
			return invalid("action identity")
		}
		if action.Status != SyncTxnActionIntent && action.Status != SyncTxnActionObserved && action.Status != SyncTxnActionFailed ||
			action.Status == SyncTxnActionIntent && i != len(tx.Actions)-1 {
			return invalid("action status")
		}
		refs := map[string]bool{}
		for _, ref := range repo.Refs {
			refs[ref.Ref] = true
		}
		allowed := map[string]bool{}
		for _, ref := range action.AllowedRefs {
			if !refs[ref] || allowed[ref] || action.RefLogAnchors[ref] == "" {
				return invalid("action ref ownership")
			}
			allowed[ref] = true
		}
		if !allowed[entries[action.Entry]] || action.ContextReflogAnchor == "" {
			return invalid("action attribution evidence")
		}
		if action.ContextBefore.Path != action.ContextPath ||
			action.ContextBefore != syncTransactionHolderMap(action.BeforeHolders)[action.ContextPath] ||
			action.ContextRef != "" && !allowed[action.ContextRef] {
			return invalid("action context transition")
		}
		repoHolders := map[string]bool{}
		for _, holder := range repo.Holders {
			repoHolders[holder.Path] = true
		}
		if !repoHolders[action.ContextPath] {
			return invalid("action context belongs to another repository")
		}
		for imageIndex, image := range [][]SyncTransactionHolderValue{action.BeforeHolders, action.AfterHolders} {
			if imageIndex == 1 && image == nil && action.Status == SyncTxnActionIntent {
				continue
			}
			seen := map[string]bool{}
			for _, holder := range image {
				if !repoHolders[holder.Path] || seen[holder.Path] ||
					!reparentStateOID(holder.HEAD, repo.OIDWidth) ||
					holder.Detached != (holder.Branch == "") ||
					!holder.Detached && !reparentStateRef("refs/heads/"+holder.Branch) {
					return invalid("action holder image")
				}
				seen[holder.Path] = true
			}
			if len(seen) != len(repoHolders) {
				return invalid("incomplete action holder image")
			}
		}
		for imageIndex, image := range [][]SyncTransactionRefValue{action.BeforeRefs, action.AfterRefs} {
			if imageIndex == 1 && image == nil && action.Status == SyncTxnActionIntent {
				continue
			}
			seen := map[string]bool{}
			for _, ref := range image {
				if !refs[ref.Ref] || seen[ref.Ref] || !reparentStateOID(ref.SHA, repo.OIDWidth) {
					return invalid("action ref image")
				}
				seen[ref.Ref] = true
				if imageIndex == 0 && ref.SHA != refHistory[repo.CommonDir][ref.Ref] {
					return invalid("action preimage disagrees with prior progress")
				}
				if imageIndex == 1 {
					if ref.SHA != refHistory[repo.CommonDir][ref.Ref] && !allowed[ref.Ref] {
						return invalid("action postimage changes an unowned ref")
					}
					refHistory[repo.CommonDir][ref.Ref] = ref.SHA
				}
			}
			if len(seen) != len(refs) {
				return invalid("incomplete action ref image")
			}
		}
	}
	for _, repo := range tx.Repositories {
		for _, ref := range repo.Refs {
			expected := refHistory[repo.CommonDir][ref.Ref]
			if ref.Restored {
				expected = ref.PreimageSHA
			}
			if ref.ExpectedSHA != expected {
				return invalid("expected ref does not follow recorded actions")
			}
		}
	}
	for i, validation := range tx.Validations {
		repo := repos[validation.RepoCommonDir]
		if validation.Sequence != i+1 || repo == nil || !selected[validation.Entry] ||
			!syncTransactionAbsolutePath(validation.ContextPath) || !holders[validation.ContextPath] {
			return invalid("validation identity")
		}
		switch validation.Status {
		case SyncTxnActionIntent:
			if i != len(tx.Validations)-1 {
				return invalid("pending validation is not last")
			}
		case SyncTxnActionObserved, SyncTxnActionFailed, SyncTxnActionMutated:
		default:
			return invalid("validation status")
		}
		for imageIndex, image := range [][]SyncTransactionRefValue{validation.BeforeRefs, validation.AfterRefs} {
			if imageIndex == 1 && image == nil && validation.Status == SyncTxnActionIntent {
				continue
			}
			seen := map[string]bool{}
			for _, value := range image {
				if seen[value.Ref] || !reparentStateOID(value.SHA, repo.OIDWidth) {
					return invalid("validation ref image")
				}
				known := false
				for _, ref := range repo.Refs {
					if ref.Ref == value.Ref {
						known = true
						break
					}
				}
				if !known {
					return invalid("validation ref image")
				}
				seen[value.Ref] = true
			}
			if len(seen) != len(repo.Refs) {
				return invalid("incomplete validation ref image")
			}
		}
		for imageIndex, image := range [][]SyncTransactionHolderValue{validation.BeforeHolders, validation.AfterHolders} {
			if imageIndex == 1 && image == nil && validation.Status == SyncTxnActionIntent {
				continue
			}
			seen := map[string]bool{}
			for _, holder := range image {
				if seen[holder.Path] || !holders[holder.Path] ||
					!reparentStateOID(holder.HEAD, repo.OIDWidth) ||
					holder.Detached != (holder.Branch == "") {
					return invalid("validation holder image")
				}
				seen[holder.Path] = true
			}
			if len(seen) != len(repo.Holders) {
				return invalid("incomplete validation holder image")
			}
		}
		if validation.Status == SyncTxnActionMutated &&
			reflect.DeepEqual(validation.BeforeRefs, validation.AfterRefs) &&
			reflect.DeepEqual(validation.BeforeHolders, validation.AfterHolders) {
			return invalid("validation mutation has no changed image")
		}
	}
	intents := map[string]SyncTransactionPushIntent{}
	for _, intent := range tx.Publication.Intents {
		repo := repos[intent.RepoCommonDir]
		if !selected[intent.Entry] || repo == nil || intents[intent.Entry].Entry != "" ||
			!reparentStateRef(intent.DestinationRef) ||
			!reparentStateOID(intent.SourceSHA, repo.OIDWidth) {
			return invalid("publication intent")
		}
		found := false
		for _, ref := range repo.Refs {
			if ref.Ref == intent.DestinationRef && ref.ExpectedSHA == intent.SourceSHA {
				found = true
				break
			}
		}
		if !found {
			return invalid("publication source")
		}
		intents[intent.Entry] = intent
	}
	if tx.Publication.Current != nil {
		if tx.Publication.Current.Entry != tx.Publication.CurrentEntry ||
			intents[tx.Publication.Current.Entry] != *tx.Publication.Current {
			return invalid("publication current intent")
		}
	}
	for _, result := range tx.Publication.Results {
		if intents[result.Entry].Entry == "" {
			return invalid("publication result without bound intent")
		}
	}
	return nil
}

package internal

import (
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"time"

	"gopkg.in/yaml.v3"
)

type SyncState struct {
	StartedAt    string   `yaml:"started_at"`
	FailedBranch string   `yaml:"failed_branch"`
	Pending      []string `yaml:"pending"`
	Completed    []string `yaml:"completed"`
	Skipped      []string `yaml:"skipped"`
}

func SyncStatePath(featurePath string) string {
	return filepath.Join(featurePath, ".sync-state.yaml")
}

func LoadSyncState(featurePath string) (*SyncState, error) {
	if err := syncIOFault(SyncIOReadSyncState, SyncStatePath(featurePath)); err != nil {
		return nil, err
	}
	data, err := os.ReadFile(SyncStatePath(featurePath))
	if err != nil {
		return nil, err
	}
	var s SyncState
	if err := yaml.Unmarshal(data, &s); err != nil {
		return nil, err
	}
	return &s, nil
}

func SaveSyncState(featurePath string, s *SyncState) error {
	data, err := yaml.Marshal(s)
	if err != nil {
		return err
	}
	return atomicWriteFile(SyncStatePath(featurePath), data, 0644)
}

func LoadTransactionalSyncSentinel(featurePath string) (*SyncState, error) {
	data, err := readSyncStateFile(SyncStatePath(featurePath))
	if err != nil {
		return nil, err
	}
	var sentinel SyncState
	if err := decodeStrictSyncEnvelope(data, &sentinel); err != nil {
		return nil, err
	}
	return &sentinel, nil
}

// RestoreTransactionalSyncSentinel installs a complete compatibility marker
// only if its path is still absent. The authoritative payload is not changed.
func RestoreTransactionalSyncSentinel(featurePath string, payload *SyncRunState) error {
	if err := validateSyncRunStateEnvelope(featurePath, payload); err != nil {
		return err
	}
	path := SyncStatePath(featurePath)
	if err := syncIOFault(SyncIOWriteSentinel, path); err != nil {
		return err
	}
	data, err := yaml.Marshal(&SyncState{
		StartedAt: payload.StartedAt, FailedBranch: payload.Marker,
		Pending: []string{}, Completed: []string{}, Skipped: []string{},
	})
	if err != nil {
		return err
	}
	file, err := os.CreateTemp(featurePath, ".tws-state-*")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name()) //nolint:errcheck
	defer file.Close()           //nolint:errcheck
	if err := file.Chmod(0644); err != nil {
		return err
	}
	if _, err := file.Write(data); err != nil {
		return err
	}
	if err := file.Sync(); err != nil {
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := os.Link(file.Name(), path); err != nil {
		return fmt.Errorf("restore missing sync compatibility marker without replacing existing evidence: %w", err)
	}
	return syncDir(featurePath)
}

// RemoveSyncState removes the legacy state/sentinel file, returning any error
// other than "already gone" (§12.2c rule 2).
func RemoveSyncState(featurePath string) error {
	path := SyncStatePath(featurePath)
	if err := syncIOFault(SyncIORemoveSyncState, path); err != nil {
		return err
	}
	if err := os.Remove(path); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("remove sync state %s: %w", path, err)
	}
	return nil
}

func DeleteSyncState(featurePath string) {
	_ = RemoveSyncState(featurePath)
}

func HasSyncState(featurePath string) bool {
	_, err := os.Stat(SyncStatePath(featurePath))
	return err == nil
}

func NewSyncState() *SyncState {
	return &SyncState{
		StartedAt: time.Now().UTC().Format(time.RFC3339),
	}
}

// SyncStateIOFault is §23.1 item 4's injected reader/remover/restorer/writer
// seam. It is nil in production and MUST NOT be reachable from the CLI. A
// test sets it to force a NON-ErrNotExist I/O failure at a named operation
// on a named path, which is the only way to exercise the error arms of the
// state writers on a filesystem where permissions cannot be made to fail
// (root, ACLs, CI containers). Returning nil lets the real operation
// proceed.
//
// op is one of the closed labels below; path is the artefact's absolute
// path, so a fault can be scoped to exactly one file.
var SyncStateIOFault func(op, path string) error

// The closed op label domain of SyncStateIOFault.
const (
	SyncIOReadSyncState        = "read-sync-state"        // the .sync-state.yaml capture read
	SyncIOReadSyncRunState     = "read-sync-run-state"    // the payload read path
	SyncIORemoveSyncState      = "remove-sync-state"      // §12.2c rule 2 remover
	SyncIORemoveSyncRunState   = "remove-sync-run-state"  // §12.2c rule 2 remover
	SyncIORemoveSyncRunGuard   = "remove-sync-run-guard"  // §12.2c rule 2 remover
	SyncIOWriteSentinel        = "write-sentinel"         // SaveGuardedLegacySentinel
	SyncIORestoreSyncState     = "restore-sync-state"     // RestoreSyncStateBytes
	SyncIORemoveStateUnchanged = "remove-state-unchanged" // RemoveSyncStateIfUnchanged
	SyncIOWriteSyncRunState    = "write-sync-run-state"   // SaveSyncRunState
	SyncIOWriteTransaction     = "write-checkout-tx"      // SaveCheckoutTransaction
	SyncIOReloadStack          = "reload-stack"           // the JIT seam's stack.yaml reload

	// The four safe-reparent tokens (§10.3b). They are APPENDED to the
	// domain above and are never reordered: an existing token's position
	// is part of the shipped seam's contract. Each one is consulted TWICE
	// by durableWriteFile — once before the rename and once after the
	// rename but before the parent-directory fsync — so a test can force a
	// failure in either window by counting its own invocations.
	SyncIOWriteStack           = "write-stack"           // WriteStackBytesAtomic
	SyncIOWriteReparentState   = "write-reparent-state"  // the §11.1 reparent state artifact
	SyncIOWriteReparentCompat  = "write-reparent-compat" // the §11.2 compatibility artifacts
	SyncIOWriteReparentRemote  = "write-reparent-remote" // the §12.3 remote follow-up record
	SyncIORemoveReparentRemote = "remove-reparent-remote"
)

// syncIOFault consults the injected seam. It returns nil in production,
// where SyncStateIOFault is nil.
func syncIOFault(op, path string) error {
	if SyncStateIOFault == nil {
		return nil
	}
	return SyncStateIOFault(op, path)
}

// ---------- guarded legacy rollback: conditional restore/remove ----------

// ErrSyncStateChanged and ErrSyncStateHasPayload are the two distinguished
// "restored nothing" outcomes of RestoreSyncStateBytes, RemoveSyncStateIfUnchanged
// and SaveGuardedLegacySentinel: both mean the file on disk was left exactly
// as found.
var ErrSyncStateChanged = errors.New("sync state changed since it was captured")
var ErrSyncStateHasPayload = errors.New("a scoped sync payload exists beside the sync state")

// RestoreSyncStateBytes writes prior back over .sync-state.yaml through the
// shipped atomic writer, but ONLY when both preconditions hold:
//
//  1. the file's current bytes are byte-identical to expect — the exact
//     sentinel this invocation installed — so a restore can never clobber a
//     document another party wrote (ErrSyncStateChanged otherwise); and
//  2. no scoped payload exists beside it (HasSyncRunState is false), so a
//     restore can never place a REAL legacy state next to a live payload,
//     which would be classifier cell 8 (ErrSyncStateHasPayload otherwise).
//
// The result is therefore either the captured bytes or the value the file had
// before the attempt — never a partial document and never a cell-8 pair.
// len(prior) == 0 is a programming error and returns an error rather than
// truncating the file; the caller uses RemoveSyncStateIfUnchanged for the
// fresh cell, where there were no prior bytes at all. The guarded legacy
// rollback NEVER calls the unconditional RemoveSyncState.
func RestoreSyncStateBytes(featurePath string, prior, expect []byte) error {
	if len(prior) == 0 {
		return fmt.Errorf("restore sync state: refusing to write an empty prior document")
	}
	if err := syncIOFault(SyncIORestoreSyncState, SyncStatePath(featurePath)); err != nil {
		return err
	}
	current, err := os.ReadFile(SyncStatePath(featurePath))
	if err != nil || !bytes.Equal(current, expect) {
		return ErrSyncStateChanged
	}
	if HasSyncRunState(featurePath) {
		return ErrSyncStateHasPayload
	}
	return atomicWriteFile(SyncStatePath(featurePath), prior, 0644)
}

// RemoveSyncStateIfUnchanged is the fresh route's rollback counterpart of
// RestoreSyncStateBytes: it removes .sync-state.yaml only while its bytes are
// still expect AND no payload exists beside it, returning ErrSyncStateChanged
// or ErrSyncStateHasPayload otherwise and removing nothing.
func RemoveSyncStateIfUnchanged(featurePath string, expect []byte) error {
	if err := syncIOFault(SyncIORemoveStateUnchanged, SyncStatePath(featurePath)); err != nil {
		return err
	}
	current, err := os.ReadFile(SyncStatePath(featurePath))
	if err != nil || !bytes.Equal(current, expect) {
		return ErrSyncStateChanged
	}
	if HasSyncRunState(featurePath) {
		return ErrSyncStateHasPayload
	}
	return RemoveSyncState(featurePath)
}

// ---------- the guarded legacy sentinel (§13.6 rule 2c) ----------

// GuardedLegacySentinelVersion is the guarded legacy sentinel's own version.
// It is deliberately a SEPARATE constant from SyncRunStateGuardedVersion: the
// payload and the sentinel are different documents with different readers.
const GuardedLegacySentinelVersion = 3

// GuardedLegacySentinel is .sync-state.yaml as a guarded legacy run writes
// it. The shipped SyncState is embedded INLINE and written exactly as the
// shipped sentinel writes it, so a binary whose decoder ignores unknown keys
// sees a sentinel and nothing else, and fails closed on the marker in every
// cell.
type GuardedLegacySentinel struct {
	SyncState `yaml:",inline"` // started_at, failed_branch = the marker, pending/completed/
	// skipped = [], byte-for-byte the shipped sentinel shape

	GuardedStateVersion int    `yaml:"guarded_state_version"` // always 3
	Route               string `yaml:"route"`                 // always "legacy"
	Feature             string `yaml:"feature"`
	Marker              string `yaml:"marker"`      // MUST equal FailedBranch
	OwnerToken          string `yaml:"owner_token"` // the token step 2 claimed with
	CreatedAt           string `yaml:"created_at"`  // RFC3339 UTC
	WriterPID           int    `yaml:"writer_pid"`  // diagnostic only; never a verdict

	MaxReplayPerEntry *int   `yaml:"max_replay_per_entry,omitempty"` // the EFFECTIVE limits, so a
	MaxReplayTotal    *int   `yaml:"max_replay_total,omitempty"`     // persisted 0 survives
	Push              bool   `yaml:"push"`                           // provenance; the flag still wins
	TestCommand       string `yaml:"test_command,omitempty"`         // the FROZEN validation command
	ValidationSource  string `yaml:"validation_source,omitempty"`    // its provenance. There is NO
	// digest member and no validation_digest key: §15's identity is DERIVED
	// from TestCommand by whoever needs it (§13.1 rule 2, §25.3)

	Universe []string `yaml:"universe"` // the full-stack Selected list in
	// the invocation's ONE TopoSort order
	PendingIntent     []string `yaml:"pending_intent"`        // the remaining set of §13.3
	CarriedCompleted  []string `yaml:"carried_completed"`     // the prior state's Completed, verbatim
	CarriedFailed     string   `yaml:"carried_failed_branch"` // the prior state's FailedBranch
	PriorPendingCount int      `yaml:"prior_pending_count"`   // len(prior.Pending) — the number the
	// shipped resume prints (§12.3 row 7)

	PriorLegacyPresent bool   `yaml:"prior_legacy_present"`          // false on a FRESH run only
	PriorLegacySHA256  string `yaml:"prior_legacy_sha256,omitempty"` // 64-lower-hex over the bytes
	PriorLegacyBase64  string `yaml:"prior_legacy_base64,omitempty"` // std base64 of the CAPTURED
	// bytes, verbatim
}

// SaveGuardedLegacySentinel installs the sentinel at .sync-state.yaml through
// ONE conditional atomic write at the shipped 0644 mode. expect is the
// captured prior bytes; nil means "expect the path to be absent" (the fresh
// route). The write refuses — writing nothing, returning ErrSyncStateChanged
// — when the current file is not what expect says it is, so the path is
// either the old bytes/absent or the complete sentinel, never anything
// between.
// MarshalGuardedLegacySentinel renders the exact bytes
// SaveGuardedLegacySentinel installs. Both go through this one function, so
// the setup of §13.2a can hand its rollback the precise `expect` bytes it is
// about to write without re-deriving them from a second, possibly divergent
// encoder — and without silently swallowing a marshal failure.
func MarshalGuardedLegacySentinel(s *GuardedLegacySentinel) ([]byte, error) {
	data, err := yaml.Marshal(s)
	if err != nil {
		return nil, fmt.Errorf("marshal guarded sentinel: %w", err)
	}
	return data, nil
}

func SaveGuardedLegacySentinel(featurePath string, s *GuardedLegacySentinel, expect []byte) error {
	path := SyncStatePath(featurePath)
	if err := syncIOFault(SyncIOWriteSentinel, path); err != nil {
		return err
	}
	current, err := os.ReadFile(path)
	switch {
	case err == nil:
		if expect == nil || !bytes.Equal(current, expect) {
			return ErrSyncStateChanged
		}
	case errors.Is(err, fs.ErrNotExist):
		if expect != nil {
			return ErrSyncStateChanged
		}
	default:
		return fmt.Errorf("read sync state: %w", err)
	}
	data, err := MarshalGuardedLegacySentinel(s)
	if err != nil {
		return err
	}
	if err := atomicWriteFile(path, data, 0644); err != nil {
		return fmt.Errorf("write sync sentinel: %w", err)
	}
	return nil
}

// GuardedLegacySentinelVerdict is the closed verdict domain of
// InspectGuardedLegacySentinel.
type GuardedLegacySentinelVerdict string

const (
	SentinelNotApplicable GuardedLegacySentinelVerdict = "not-applicable" // the zero value
	SentinelAbsent        GuardedLegacySentinelVerdict = "absent"
	SentinelNotGuarded    GuardedLegacySentinelVerdict = "not-guarded" // real legacy state, or
	// a PLAIN shipped sentinel
	SentinelValid        GuardedLegacySentinelVerdict = "valid"
	SentinelSymlink      GuardedLegacySentinelVerdict = "symlink"
	SentinelUnreadable   GuardedLegacySentinelVerdict = "unreadable"
	SentinelUnsupported  GuardedLegacySentinelVerdict = "unsupported-version"
	SentinelCorrupt      GuardedLegacySentinelVerdict = "corrupt"
	SentinelForeign      GuardedLegacySentinelVerdict = "foreign"
	SentinelHashMismatch GuardedLegacySentinelVerdict = "hash-mismatch"
)

// GuardedLegacySentinelView is the decided view. Sentinel and Prior are
// non-nil ONLY under SentinelValid, so no caller can resume from a document
// this ladder did not accept.
type GuardedLegacySentinelView struct {
	Verdict  GuardedLegacySentinelVerdict
	Path     string
	Sentinel *GuardedLegacySentinel // the decoded extension
	Prior    *SyncState             // the VERIFIED backed-up legacy state; nil when
	// PriorLegacyPresent is false
	Version int   // the raw guarded_state_version, for the unsupported sentence
	Err     error // the underlying I/O or decode error; sanitized by cli
}

// isLowerHex64 reports whether s is exactly 64 lowercase hex characters, the
// shape of a SHA-256 digest as this sentinel persists it.
func isLowerHex64(s string) bool {
	if len(s) != 64 {
		return false
	}
	for _, r := range s {
		if (r < '0' || r > '9') && (r < 'a' || r > 'f') {
			return false
		}
	}
	return true
}

// InspectGuardedLegacySentinel performs ONE Lstat and at most ONE read of a
// regular file, follows no symlink, and applies the ordered ladder of §13.6
// rule 2c: the first failing clause decides, and only SentinelValid resumes.
// It refuses nothing and prints nothing: internal decides, cli speaks.
func InspectGuardedLegacySentinel(featurePath, feature string) GuardedLegacySentinelView {
	path := SyncStatePath(featurePath)
	view := GuardedLegacySentinelView{Path: path}

	info, err := os.Lstat(path)
	switch {
	case errors.Is(err, fs.ErrNotExist):
		view.Verdict = SentinelAbsent
		return view
	case err != nil:
		view.Verdict = SentinelUnreadable
		view.Err = err
		return view
	case info.Mode()&os.ModeSymlink != 0:
		view.Verdict = SentinelSymlink
		return view
	case !info.Mode().IsRegular():
		view.Verdict = SentinelUnreadable
		return view
	}

	data, err := os.ReadFile(path)
	if err != nil {
		view.Verdict = SentinelUnreadable
		view.Err = err
		return view
	}
	if len(data) == 0 {
		view.Verdict = SentinelUnreadable
		return view
	}
	var raw GuardedLegacySentinel
	if err := yaml.Unmarshal(data, &raw); err != nil {
		view.Verdict = SentinelUnreadable
		view.Err = err
		return view
	}

	if !isSyncMarker(raw.FailedBranch) {
		view.Verdict = SentinelNotGuarded
		return view
	}
	if raw.GuardedStateVersion == 0 {
		view.Verdict = SentinelNotGuarded
		return view
	}
	if raw.GuardedStateVersion != GuardedLegacySentinelVersion {
		view.Verdict = SentinelUnsupported
		view.Version = raw.GuardedStateVersion
		return view
	}
	if raw.Route != RouteLegacy || raw.Marker != raw.FailedBranch || !isSyncMarker(raw.Marker) ||
		raw.OwnerToken == "" || raw.Feature == "" {
		view.Verdict = SentinelCorrupt
		return view
	}
	if raw.Feature != feature {
		view.Verdict = SentinelForeign
		return view
	}

	if !raw.PriorLegacyPresent {
		if raw.PriorLegacyBase64 != "" || raw.PriorLegacySHA256 != "" || raw.PriorPendingCount != 0 ||
			len(raw.CarriedCompleted) != 0 || raw.CarriedFailed != "" {
			view.Verdict = SentinelCorrupt
			return view
		}
		view.Verdict = SentinelValid
		view.Sentinel = &raw
		return view
	}

	decoded, err := base64.StdEncoding.DecodeString(raw.PriorLegacyBase64)
	if err != nil {
		view.Verdict = SentinelHashMismatch
		return view
	}
	if !isLowerHex64(raw.PriorLegacySHA256) {
		view.Verdict = SentinelHashMismatch
		return view
	}
	sum := sha256.Sum256(decoded)
	if raw.PriorLegacySHA256 != hex.EncodeToString(sum[:]) {
		view.Verdict = SentinelHashMismatch
		return view
	}

	var prior SyncState
	if err := yaml.Unmarshal(decoded, &prior); err != nil {
		view.Verdict = SentinelCorrupt
		return view
	}
	if isSyncMarker(prior.FailedBranch) {
		view.Verdict = SentinelCorrupt
		return view
	}
	if raw.PriorPendingCount != len(prior.Pending) {
		view.Verdict = SentinelCorrupt
		return view
	}

	view.Verdict = SentinelValid
	view.Sentinel = &raw
	view.Prior = &prior
	return view
}

// GuardedLegacySentinelResumable is the ONE dispatch predicate (§19.2): a
// classifier cell 4 — sentinel present, payload absent — whose sentinel this
// ladder accepted. It is evaluated on NO other cell.
func GuardedLegacySentinelResumable(st SyncExternalState, v GuardedLegacySentinelView) bool {
	return st.Cell == 4 && v.Verdict == SentinelValid
}
